// chanceify™ song page: a Cloudflare Worker that makes the link "Copy the song
// for Discord" gives out. Discord, and anyone who opens it, sees the cover,
// the song, and a button that opens it in Spotify. No keys, no secrets.
//
//   https://<your-worker>.workers.dev/t/<spotify track id>?t=<title>&a=<artist>
//
// The cover comes from Spotify's public oEmbed. The title and artist come from
// the link itself (chanceify puts them there), with oEmbed as the fallback.

// chance's little icons: one picked at random each time the page opens.
const ICONS = ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"];

const VERSION = "worker 8";
// One worker, four kinds of page: /t/ song, /a/ artist, /p/ playlist, /u/ profile.
const KIND = { t: "track", a: "artist", p: "playlist", u: "user" };
const WORDS = { t: "A song", a: "An artist", p: "A playlist", u: "A profile" };
const esc = (s) =>
  String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

export default {
  async fetch(request) {
    const url = new URL(request.url);
    // The cover, passed through from this address so the swirl behind the page
    // is allowed to read its pixels (Spotify's picture server does not allow it).
    const cover = url.pathname.match(/^\/c\/(?:([tapu])\/)?([A-Za-z0-9._-]{2,40})$/);
    if (cover) {
      try {
        const meta = await fetch(
          "https://open.spotify.com/oembed?url=" + encodeURIComponent("https://open.spotify.com/" + KIND[cover[1] || "t"] + "/" + cover[2]),
          { cf: { cacheTtl: 3600, cacheEverything: true } },
        );
        const thumb = (await meta.json()).thumbnail_url;
        if (typeof thumb === "string" && /^https:\/\/i\.scdn\.co\//.test(thumb)) {
          const picture = await fetch(thumb, { cf: { cacheTtl: 86400, cacheEverything: true } });
          if (picture.ok) {
            return new Response(picture.body, {
              headers: {
                "content-type": picture.headers.get("content-type") || "image/jpeg",
                "access-control-allow-origin": "*",
                "cache-control": "public, max-age=86400",
              },
            });
          }
        }
      } catch (_) {}
      return new Response("", { status: 404 });
    }
    if (url.pathname === "/version") {
      return new Response(JSON.stringify({ worker: VERSION }), { headers: { "content-type": "application/json", "access-control-allow-origin": "*", "cache-control": "no-store" } });
    }
    const match = url.pathname.match(/^\/([tapu])\/([A-Za-z0-9._-]{2,40})\/?$/);
    if (!match) {
      return new Response(page({ title: "chanceify™", artist: "A Spotify player by chance", id: null }), html());
    }
    const kind = match[1];
    const id = match[2];
    let title = (url.searchParams.get("t") || "").slice(0, 150);
    const artist = (url.searchParams.get("a") || "").slice(0, 150);
    let image = "";
    try {
      const res = await fetch(
        "https://open.spotify.com/oembed?url=" + encodeURIComponent("https://open.spotify.com/" + KIND[kind] + "/" + id),
        { cf: { cacheTtl: 3600, cacheEverything: true } },
      );
      if (res.ok) {
        const data = await res.json();
        image = data.thumbnail_url || "";
        if (!title) title = data.title || "";
      }
    } catch (_) {}
    return new Response(page({ title: title || WORDS[kind], artist, id, image, kind }), html());
  },
};

const html = () => ({ headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache" } });

function page({ title, artist, id, image, kind = "t" }) {
  const spotify = id ? `https://open.spotify.com/${KIND[kind]}/${id}` : "https://github.com/madlygeeked/chanceify";
  const line = artist ? `${artist}` : "Listening on chanceify™";
  const desc = artist ? `${artist}. Listening on chanceify™` : "Listening on chanceify™";
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(title)} - chanceify™</title>
<meta name="theme-color" content="#8b5cf6">
<meta property="og:type" content="music.song">
<meta property="og:site_name" content="chanceify™">
<meta property="og:title" content="${esc(title)}">
<meta property="og:description" content="${esc(desc)}">
${image ? `<meta property="og:image" content="${esc(image)}">` : ""}
<meta name="twitter:card" content="summary_large_image">
${image ? `<meta name="twitter:image" content="${esc(image)}">
<meta property="og:image:width" content="640">
<meta property="og:image:height" content="640">` : ""}
<style>
:root{color-scheme:dark}
*{box-sizing:border-box}
body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;font-family:system-ui,"Segoe UI",sans-serif;color:#f3f0ff;
background:radial-gradient(900px 600px at 20% 10%,#4c1d95 0,transparent 60%),radial-gradient(800px 600px at 90% 90%,#312e81 0,transparent 60%),#0f0b1d}
.card{width:min(420px,100%);text-align:center}
.cover{width:100%;aspect-ratio:1;border-radius:22px;background:#241a45 center/cover;box-shadow:0 30px 80px #0009,0 0 0 1px #ffffff1a}
h1{font-size:26px;margin:22px 0 4px;line-height:1.2}
p{margin:0;color:#c4b5fd;font-size:16px}
.btn{display:block;text-align:center;padding:13px 28px;border-radius:999px;background:linear-gradient(90deg,#3b82f6,#8b5cf6);color:#fff;font-weight:600;text-decoration:none}
.btn:hover{filter:brightness(1.12)}
.row{margin-top:14px;display:flex;gap:10px;justify-content:center;flex-wrap:wrap}
.stack{margin-top:24px;flex-direction:column;align-items:stretch}
.btn.yt{background:#e62117;color:#fff;font-weight:600}
.btn.sc{background:#ff5500;color:#fff;font-weight:600}
.btn.sp{background:#1db954;color:#fff;font-weight:600}
.btn.alt{background:#ffffff14;border:1px solid #a78bfa55;color:#ede9fe;font-weight:500}
.btn.alt:hover{background:#a78bfa2a}
.play{margin-top:18px;border:0;border-radius:14px;color-scheme:normal}
.bear{height:1.5em;width:auto;vertical-align:middle;margin-left:6px}
#swirl{position:fixed;inset:0;width:100%;height:100%;z-index:-1}
.card{position:relative}
.foot{margin-top:28px;font-size:13px;color:#a78bfa99}
.foot a{color:inherit}
</style></head><body>
<canvas id="swirl"></canvas>
<main class="card">
<div class="cover"${image ? ` style="background-image:url('${esc(image)}')"` : ""}></div>
<h1>${esc(title)}</h1>
<p>${esc(line)}</p>
${id ? `<div class="row stack">${kind !== "u" ? `<a class="btn" href="chanceify://${KIND[kind]}/${esc(id)}">Open in chanceify</a>` : ""}
<a class="btn yt" href="https://www.youtube.com/results?search_query=${encodeURIComponent((artist ? artist + " " : "") + title)}" target="_blank" rel="noopener">Search on YouTube</a>
<a class="btn sc" href="https://soundcloud.com/search?q=${encodeURIComponent((artist ? artist + " " : "") + title)}" target="_blank" rel="noopener">Search on SoundCloud</a>
<a class="btn sp" href="${esc(spotify)}">Open in Spotify</a></div>
${kind === "u" ? "" : `<iframe class="play" title="Play a preview" src="https://open.spotify.com/embed/${KIND[kind]}/${esc(id)}?theme=0" width="100%" height="152" frameborder="0" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" loading="lazy"></iframe>`}` : ""}
<div class="foot">Built with love by <a href="https://madlygeeked.github.io/">chance</a><img class="bear" id="bear" alt=""></div>
</main>
<script>
// The cover, bent into the same liquid swirl chanceify draws, drifting slowly.
(function(){
  var icons=${JSON.stringify(ICONS)},bear=document.getElementById("bear");
  if(bear)bear.src=icons[Math.floor(Math.random()*icons.length)];
  var cv=document.getElementById("swirl");
  var V=${JSON.stringify(VERSION)},st=document.getElementById("stamp");
  function say(m){}
  say("starting");
  var gl=cv.getContext("webgl",{antialias:false});
  var urls=${JSON.stringify(id ? ["/c/" + kind + "/" + id, image || ""].filter(Boolean) : [])};
  if(!gl){say("this browser has no WebGL (gradient only)");return}
  var still=matchMedia("(prefers-reduced-motion: reduce)").matches;
  function sh(type,src){var o=gl.createShader(type);gl.shaderSource(o,src);gl.compileShader(o);return o}
  var vs="attribute vec2 p;void main(){gl_Position=vec4(p,0.,1.);}";
  var fs="precision mediump float;uniform sampler2D tex;uniform float t;uniform vec2 res;"+
  "vec3 mir(vec2 p){return texture2D(tex,0.5-0.5*cos(6.2831853*p)).rgb;}"+
  "void main(){vec2 uv=gl_FragCoord.xy/res;uv.y=1.-uv.y;uv.x*=res.x/res.y*0.62;"+
  "float tau=6.2831853;float rise=0.8;"+
  "float w1=sin(tau*(-2.*uv.x-uv.y)+0.7+t*0.30);"+
  "float w2=sin(tau*(uv.x-uv.y)+2.1+t*0.21);"+
  "float a=atan(-0.316,-0.949);vec2 off=vec2(sin(a),-cos(a));"+
  "vec2 p=uv+w1*off*0.55*rise+vec2(w2*0.12*rise,-w2*0.09*rise);"+
  "vec3 c=vec3(0.);float tw=0.;"+
  "for(int i=-2;i<=2;i++)for(int j=-2;j<=2;j++){float w=exp(-float(i*i+j*j)/3.);c+=mir(p+vec2(float(i),float(j))*0.006)*w;tw+=w;}"+
  "c/=tw;float l=dot(c,vec3(.299,.587,.114));c=l+(c-l)*1.45;c=(c-0.5)*1.2+0.5;"+
  "float v=smoothstep(1.1,0.2,length(gl_FragCoord.xy/res-0.5)*1.5);gl_FragColor=vec4(clamp(c*(0.30+0.18*v),0.,1.),1.);}";
  var pr=gl.createProgram();gl.attachShader(pr,sh(gl.VERTEX_SHADER,vs));gl.attachShader(pr,sh(gl.FRAGMENT_SHADER,fs));gl.linkProgram(pr);
  if(!gl.getProgramParameter(pr,gl.LINK_STATUS)){say("shader failed: "+gl.getProgramInfoLog(pr));return}
  gl.useProgram(pr);
  var buf=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buf);
  gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);
  var loc=gl.getAttribLocation(pr,"p");gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,2,gl.FLOAT,false,0,0);
  var uT=gl.getUniformLocation(pr,"t"),uR=gl.getUniformLocation(pr,"res");
  function size(){cv.width=Math.max(2,innerWidth>>1);cv.height=Math.max(2,innerHeight>>1);gl.viewport(0,0,cv.width,cv.height)}
  size();addEventListener("resize",size);
  function start(src,how){say(how);
    var tx=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,tx);
    gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,src);
    gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
    var t0=performance.now();
    function frame(){
      gl.uniform1f(uT,still?3:(performance.now()-t0)/1000);gl.uniform2f(uR,cv.width,cv.height);
      gl.drawArrays(gl.TRIANGLE_STRIP,0,4);
      if(!still)requestAnimationFrame(frame);
    }
    frame();
  }
  // No cover to read (or it would not load): a purple and blue picture, so
  // there is always a swirl.
  function fallback(){
    var c=document.createElement("canvas");c.width=c.height=128;var x=c.getContext("2d");
    var g2=x.createLinearGradient(0,0,128,128);
    g2.addColorStop(0,"#6d28d9");g2.addColorStop(0.5,"#2563eb");g2.addColorStop(1,"#db2777");
    x.fillStyle=g2;x.fillRect(0,0,128,128);
    x.fillStyle="rgba(255,255,255,.18)";x.beginPath();x.arc(40,50,26,0,7);x.fill();
    x.fillStyle="rgba(0,0,0,.25)";x.beginPath();x.arc(92,86,30,0,7);x.fill();
    start(c,"on, built-in colours (cover could not load)");
  }
  function load(i){
    if(i>=urls.length){fallback();return}
    var im=new Image();im.crossOrigin="anonymous";
    im.onload=function(){try{start(im,i==0?"on, cover via this worker":"on, cover direct")}catch(e){load(i+1)}};
    im.onerror=function(){load(i+1)};
    im.src=urls[i];
  }
  load(0);
})();
</script>
</body></html>`;
}
